/**
 * @name Command Injection in pkgconfig
 * @description Detects command injection in pkgconfig.py
 * @kind path-problem
 * @problem.severity error
 * @id py/cffi/pkgconfig-injection
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module PkgConfigInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::ParameterNode p |
      p.getScope().getName() = "call" and
      p.getLocation().getFile().getRelativePath().matches("%cffi/pkgconfig.py") and
      source = p
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("subprocess").getMember("check_output").getACall() and
      sink = call.getArg(0)
    )
  }
}

module PkgConfigInjectionFlow = TaintTracking::Global<PkgConfigInjectionConfig>;
import PkgConfigInjectionFlow::PathGraph

from PkgConfigInjectionFlow::PathNode source, PkgConfigInjectionFlow::PathNode sink
where PkgConfigInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "parameter"
